quotes.text:
& a[is="in-app-notification-button"] {
  align-self: end;
  background: var(--button-background);
  border: 1px solid var(--button-stroke);
  border-radius: 3px;
  color: var(--button-text);
  font-weight: bold;
  padding: 6px 20px;
  text-decoration: none;
  text-wrap: nowrap;
  overflow: clip;
  text-overflow: ellipsis;
  max-inline-size: calc(100% - 52px);

  &:hover,
  &:focus {
    text-decoration: none;
    background: var(--button-background-hover);
    border: 1px solid var(--button-stroke-hover, var(--button-stroke));
  }

  &:focus-visible {
    outline: 2px solid var(--button-focus-ring);
    border: 1px solid var(--button-stroke-hover, var(--button-stroke));
    outline-offset: 2px;
  }

  &:active {
    background: var(--button-background-active);
    border: 1px solid var(--button-stroke-hover, var(--button-stroke));
    color: var(--button-text-active, var(--button-text));
  }
}

& .icon {
  position: absolute;
  z-index: 9;
  pointer-events: none;
  content: var(--icon-url);
  -moz-context-properties: fill, stroke;
  fill: var(--icon-fill);
  stroke: var(--icon-stroke);

  &:dir(rtl) {
    transform: scaleX(-1);
  }

.in-app-notification-instructions {
  clip: rect(1px, 1px, 1px, 1px);
  clip-path: inset(50%);
  margin: -1px;
  overflow: hidden;
  padding: 0;
  position: absolute;
}
